{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "properties": {
    "preset": {
      "type": "string"
    },
    "setDefaultAgent": {
      "type": "boolean"
    },
    "autoUpdate": {
      "description": "Disable automatic installation of plugin updates when false. Defaults to true.",
      "type": "boolean"
    },
    "customInstruction": {
      "description": "Text prepended verbatim to the orchestrator system prompt. Supports multiline content.",
      "type": "string"
    },
    "presets": {
      "type": "object",
      "propertyNames": {
        "type": "string"
      },
      "additionalProperties": {
        "type": "object",
        "properties": {
          "customInstruction": {
            "description": "Optional orchestrator instruction applied when this preset is active. Root-level customInstruction overrides it.",
            "type": "string"
          }
        },
        "additionalProperties": {
          "type": "object",
          "properties": {
            "default": {
              "type": "object",
              "properties": {
                "model": {
                  "type": "string",
                  "minLength": 1
                },
                "thinking": {
                  "type": "boolean"
                },
                "variants": {
                  "minItems": 1,
                  "type": "array",
                  "items": {
                    "type": "string",
                    "minLength": 1
                  }
                }
              },
              "required": [
                "model"
              ]
            },
            "smart": {
              "type": "object",
              "properties": {
                "model": {
                  "type": "string",
                  "minLength": 1
                },
                "thinking": {
                  "type": "boolean"
                },
                "variants": {
                  "minItems": 1,
                  "type": "array",
                  "items": {
                    "type": "string",
                    "minLength": 1
                  }
                }
              },
              "required": [
                "model"
              ]
            },
            "model": {
              "type": "string"
            },
            "thinking": {
              "type": "boolean"
            },
            "variants": {
              "minItems": 1,
              "type": "array",
              "items": {
                "type": "string",
                "minLength": 1
              }
            },
            "temperature": {
              "type": "number",
              "minimum": 0,
              "maximum": 2
            },
            "options": {
              "type": "object",
              "propertyNames": {
                "type": "string"
              },
              "additionalProperties": {}
            },
            "displayName": {
              "type": "string",
              "minLength": 1
            }
          },
          "additionalProperties": {}
        }
      }
    },
    "agents": {
      "type": "object",
      "propertyNames": {
        "type": "string"
      },
      "additionalProperties": {
        "type": "object",
        "properties": {
          "default": {
            "type": "object",
            "properties": {
              "model": {
                "type": "string",
                "minLength": 1
              },
              "thinking": {
                "type": "boolean"
              },
              "variants": {
                "minItems": 1,
                "type": "array",
                "items": {
                  "type": "string",
                  "minLength": 1
                }
              }
            },
            "required": [
              "model"
            ]
          },
          "smart": {
            "type": "object",
            "properties": {
              "model": {
                "type": "string",
                "minLength": 1
              },
              "thinking": {
                "type": "boolean"
              },
              "variants": {
                "minItems": 1,
                "type": "array",
                "items": {
                  "type": "string",
                  "minLength": 1
                }
              }
            },
            "required": [
              "model"
            ]
          },
          "model": {
            "type": "string"
          },
          "thinking": {
            "type": "boolean"
          },
          "variants": {
            "minItems": 1,
            "type": "array",
            "items": {
              "type": "string",
              "minLength": 1
            }
          },
          "temperature": {
            "type": "number",
            "minimum": 0,
            "maximum": 2
          },
          "options": {
            "type": "object",
            "propertyNames": {
              "type": "string"
            },
            "additionalProperties": {}
          },
          "displayName": {
            "type": "string",
            "minLength": 1
          }
        },
        "additionalProperties": {}
      }
    },
    "websearch": {
      "type": "object",
      "properties": {
        "provider": {
          "default": "exa",
          "type": "string",
          "enum": [
            "exa",
            "tavily"
          ]
        }
      }
    },
    "sessionManager": {
      "type": "object",
      "properties": {
        "maxSessionsPerAgent": {
          "default": 2,
          "type": "integer",
          "minimum": 1,
          "maximum": 10
        },
        "readContextMinLines": {
          "default": 10,
          "type": "integer",
          "minimum": 0,
          "maximum": 1000
        },
        "readContextMaxFiles": {
          "default": 8,
          "type": "integer",
          "minimum": 0,
          "maximum": 50
        }
      }
    },
    "todoContinuation": {
      "type": "object",
      "properties": {
        "maxContinuations": {
          "default": 5,
          "description": "Maximum consecutive auto-continuations before stopping to ask user",
          "type": "integer",
          "minimum": 1,
          "maximum": 50
        },
        "cooldownMs": {
          "default": 3000,
          "description": "Delay in ms before auto-continuing (gives user time to abort)",
          "type": "integer",
          "minimum": 0,
          "maximum": 30000
        },
        "autoEnable": {
          "default": false,
          "description": "Automatically enable auto-continue when the orchestrator session has enough todos",
          "type": "boolean"
        },
        "autoEnableThreshold": {
          "default": 4,
          "description": "Number of todos that triggers auto-enable (only used when autoEnable is true)",
          "type": "integer",
          "minimum": 1,
          "maximum": 50
        }
      }
    },
    "contextPressure": {
      "type": "object",
      "properties": {
        "enabled": {
          "default": true,
          "description": "When true, warn the orchestrator on high context usage before the model fails.",
          "type": "boolean"
        },
        "warnThresholdPct": {
          "default": 75,
          "description": "Inject a /compact reminder when context (used ÷ limit) is at least this percent.",
          "type": "number",
          "minimum": 1,
          "maximum": 99
        }
      }
    },
    "handoffArtifacts": {
      "type": "object",
      "properties": {
        "location": {
          "default": "project",
          "description": "Store subagent handoff artifacts in the project (.opencode-dux) or in the app cache to avoid repo clutter.",
          "type": "string",
          "enum": [
            "project",
            "cache"
          ]
        }
      }
    }
  },
  "title": "opencode-dux",
  "description": "Configuration schema for opencode-dux plugin for OpenCode"
}
